 }Time.timeScale=1;Check(m.rules.Phase==HockeyPhase.Finished&&m.rules.Winner>=0&&m.rules.Goals>0,"complete physical six-AI match declares winner from real goals");Check(m.rules.Remaining<=.001f&&m.rules.Goals==m.rules.Score.Sum(),"regulation expires and each real goal is awarded once, including overtime if tied");Check(peakTruck>3&&peakTruck<60&&peakPuck>2&&peakPuck<90,"real truck/puck motion progresses within broad simulation-failure limits");Check(m.players.Select(p=>((ISportsParticipantSlot)p).ParticipantId).SequenceEqual(ids),"rematches retain stable identities despite duplicate names");log.AppendLine("MATCH game="+game+" difficulty="+m.players[0].difficulty+" score="+string.Join(",",m.rules.Score)+" winner="+m.rules.Winner+" goals="+m.rules.Goals+" overtime="+m.rules.Overtime+" recoveries="+m.EmergencyFaceoffs+" resets="+m.rules.Resets+" strongContacts="+(m.impacts!=null?m.impacts.StrongHits:0)+" counters="+(m.impacts!=null?m.impacts.Counters:0)+" stickSwitches="+m.trucks.Sum(t=>t.stick!=null?t.stick.Switches:0)+" peakTruck="+peakTruck.ToString("F2")+" peakPuck="+peakPuck.ToString("F2")+" realSeconds="+(Time.realtimeSinceStartupAsDouble-began).ToString("F2"));if(game==3){Check(frameSum>=175,"normal-time run samples a full regulation interval with all six AI active");log.AppendLine("OBSERVATION six-AI normal-time activeFrames="+frameCount+" activeSeconds="+frameSum.ToString("F2")+" meanFrameMs="+(frameCount>0?frameSum*1000/frameCount:0).ToString("F2")+" mainSamples="+cpuSamples+" meanMainMs="+(cpuSamples>0?cpuSum/(double)cpuSamples/1000000:0).ToString("F2")+" mainCounterAvailable="+(cpuSamples>0)+" GC0="+(GC.CollectionCount(0)-gc)+" managedDelta="+(GC.GetTotalMemory(false)-memory)+" GPU="+SystemInfo.graphicsDeviceName+" context="+(Application.isEditor?"Editor":"Windows player")+" · uncontrolled host load, no isolated GPU benchmark");}Write();}
 // Explicit recovery/query fixtures, separate from autonomous match outcomes.
